mapper.select:
/* saleson.shop.mypage.MypageMapper.intrstLocGovCnt */
SELECT COUNT(a.LOCGOV_CODE)
FROM g_intrst_locgov a, g_locgov b , op_user c
WHERE a.locgov_code = b.LOCGOV_CODE
AND a.user_id = c.user_id
AND a.user_id=#{userId}

mapper.delete:
/* saleson.shop.mypage.MypageMapper.deleteIntrstLocGov */
DELETE FROM g_intrst_locgov
WHERE locgov_code = #{locgovCode}
AND user_id = #{userId}

mapper.select:
	/* saleson.shop.mypage.MypageMapper.cntrPointTotal */
	SELECT IFNULL(SUM(a.cntr_point),0) as cntr_point
	FROM g_cntr a, op_user b
	WHERE a.user_id = b.user_id
	AND b.user_id = #{userId}
	AND a.delete_at = 'N'

    	and a.cntr_locgov_code = #{locgovCode}

	/* saleson.shop.mypage.MypageMapper.usePointTotal */
	SELECT IFNULL(SUM(c.cntr_use_point),0) as cntr_use_point
	FROM g_cntr a, op_user b, g_cntr_use_point c
	WHERE a.USER_ID = b.USER_ID
	AND b.USER_ID = #{userId}
	AND b.user_id = c.user_id
	AND a.cntr_sn = c.cntr_sn
	AND a.delete_at = 'N'

    	and a.cntr_locgov_code = #{locgovCode}

/* saleson.shop.mypage.MypageMapper.getGntrListTotalCnt */ SELECT count(a.cntr_sn) as cntr_sn FROM g_cntr a, op_user b, g_locgov c WHERE a.user_id = b.user_id AND a.cntr_locgov_code = c.locgov_code AND b.user_id = #{userId} AND a.delete_at = 'N'
and a.cntr_locgov_code = #{locgovCode}
and c.upper_locgov_code = #{upperLocgovCode}
and a.cntr_de LIKE CONCAT(#{searchYear}, '%')
and a.cntr_de = DATE_FORMAT(SYSDATE,'%Y%m%d')
and a.cntr_de >= DATE_FORMAT(DATE_SUB(SYSDATE, INTERVAL 7 DAY ),'%Y%m%d')
and a.cntr_de >= DATE_FORMAT(DATE_SUB(SYSDATE, INTERVAL 1 MONTH ),'%Y%m%d')
and a.cntr_de >= DATE_FORMAT(DATE_SUB(SYSDATE, INTERVAL 3 MONTH ),'%Y%m%d')
and a.cntr_de >= DATE_FORMAT(DATE_SUB(SYSDATE, INTERVAL 6 MONTH ),'%Y%m%d')
and a.cntr_de >= DATE_FORMAT(DATE_SUB(SYSDATE, INTERVAL 1 YEAR ),'%Y%m%d')

/* saleson.shop.mypage.MypageMapper.getCntrListInfo */ SELECT a.cntr_sn, DATE_FORMAT(a.cntr_de, '%Y.%m.%d') as cntr_de, c.locgov_code, c.upper_locgov_nm, c.locgov_nm, a.cntr_amt, a.cntr_point, a.cntr_blce_point, a.elctrn_pay_no, case when a.sttemnt_pay_de is not null and cntr_sttus_code = '200' then DATE_FORMAT(a.sttemnt_pay_de, '%Y.%m.%d') else '납부결과확인' end as sttemnt_pay_de, case when a.sttemnt_pay_de is not null and cntr_sttus_code = '200' then 1 else 2 end as sttemnt_pay_de_case, a.cntr_locgov_code, case when substr(a.cntr_locgov_code,1,2) = '11' then (select to_char(sysdatetime, 'hh24missFF') || lpad(random() % 1000, 3, 0)) else (select mng_htm5 from gif_stnd_buga_now where elct_pay_no = a.elctrn_pay_no) end as mng_no, (select point_rate from g_ctbny_setup where locgov_code = a.cntr_locgov_code and stdr_year = DATE_FORMAT(NOW(),'%Y')) as point_rate , A.DSGN_DNTN_BIZ_ID AS PRJ_ID , IFNULL(DPM.DSGN_DNTN_BIZ_TTL, '자치단체기부') AS PRJ_SUBJECT , D.DETAIL , A.LINK_INSTT_CD FROM OP_USER B JOIN G_CNTR A ON A.USER_ID = B.USER_ID JOIN G_LOCGOV C ON A.CNTR_LOCGOV_CODE = C.LOCGOV_CODE LEFT JOIN G_DSGN_DNTN_BIZ_MNG DPM ON A.DSGN_DNTN_BIZ_ID = DPM.DSGN_DNTN_BIZ_ID LEFT JOIN OP_COMMON_CODE D ON D.ID = A.LINK_INSTT_CD AND D.CODE_TYPE = 'LINK_INSTT_CD' WHERE A.DELETE_AT = 'N' AND B.USER_ID = #{userId}
and a.cntr_locgov_code = #{locgovCode}
and c.upper_locgov_code = #{upperLocgovCode}
and a.cntr_de LIKE CONCAT(#{searchYear}, '%')
and a.cntr_de = DATE_FORMAT(SYSDATE,'%Y%m%d')
and a.cntr_de >= DATE_FORMAT(DATE_SUB(SYSDATE, INTERVAL 7 DAY ),'%Y%m%d')
and a.cntr_de >= DATE_FORMAT(DATE_SUB(SYSDATE, INTERVAL 1 MONTH ),'%Y%m%d')
and a.cntr_de >= DATE_FORMAT(DATE_SUB(SYSDATE, INTERVAL 3 MONTH ),'%Y%m%d')
and a.cntr_de >= DATE_FORMAT(DATE_SUB(SYSDATE, INTERVAL 6 MONTH ),'%Y%m%d')
and a.cntr_de >= DATE_FORMAT(DATE_SUB(SYSDATE, INTERVAL 1 YEAR ),'%Y%m%d')
ORDER BY a.frst_regist_pnttm DESC

/* saleson.shop.mypage.MypageMapper.blcePointTotal */
SELECT
	IFNULL(SUM(CNTR_POINT), 0) - IFNULL(SUM(cntr_use_point), 0)
FROM
(
	SELECT
		GC.CNTR_POINT
	    , (SELECT IFNULL(SUM(CNTR_USE_POINT),0) FROM G_CNTR_USE_POINT A WHERE A.CNTR_SN = GC.CNTR_SN AND A.use_se_code = '1') AS CNTR_USE_POINT
	FROM G_CNTR GC
	WHERE GC.DELETE_AT = 'N' AND GC.STTEMNT_PAY_DE IS NOT NULL AND GC.user_id = #{userId}

    	and GC.cntr_locgov_code = #{locgovCode}

) A

/* saleson.shop.mypage.MypageMapper.getLocgovNm */
SELECT
	LOCGOV_NM,
	UPPER_LOCGOV_NM
FROM G_LOCGOV
WHERE LOCGOV_CODE = #{locgovCode}


	/* saleson.shop.mypage.MypageMapper.getTaxRedutionEstimate */
	select case
	   when cntr_amt <= 100000 then cntr_amt
       when cntr_amt > 100000 then (((cntr_amt - 100000) * 0.165) + 100000)
       end as cntr_amt
	from (
		select IFNULL(SUM(cntr_amt),0) as cntr_amt
		from g_cntr
		where user_id = #{userId}
		and sttemnt_pay_de like concat( to_char(sysdate, 'yyyy') ,'%')
		and delete_at = 'N'
		and cntr_sttus_code = '200'
	)

/* saleson.shop.mypage.MypageMapper.getCntrReceipt */
SELECT CNTR_SN
       ,CNTR_LOCGOV_CODE AS LOCGOV_CODE
  FROM G_CNTR  A, OP_USER  B , OP_USER_DETAIL C
 WHERE A.USER_ID =B.USER_ID
   AND B.USER_ID =C.USER_ID
   AND A.CNTR_SN = #{cntrSn}
   AND A.USER_ID = #{userId}

