mapper.select:
/* saleson.shop.mypage.MypageMapper.getCntrListInfo */ SELECT IFNULL(SUM(a.cntr_amt),0) as cntr_amt ,count(*) as cntr_cnt FROM OP_USER B JOIN G_CNTR A ON A.USER_ID = B.USER_ID JOIN G_LOCGOV C ON A.CNTR_LOCGOV_CODE = C.LOCGOV_CODE WHERE A.DELETE_AT = 'N' AND A.CNTR_STTUS_CODE = '200' AND B.USER_ID = #{userId}
and a.cntr_locgov_code = #{locgovCode}
and c.upper_locgov_code = #{upperLocgovCode}
and a.cntr_de BETWEEN DATE_FORMAT(#{searchStartDate},'%Y%m%d') AND DATE_FORMAT(#{searchEndDate},'%Y%m%d')

/* saleson.shop.mypage.MypageMapper.getReceiptListInfo */ SELECT A.CNTR_SN , DATE_FORMAT(A.CNTR_DE, '%Y.%c.%e.') as cntr_de, C.LOCGOV_CODE, C.UPPER_LOCGOV_NM, C.LOCGOV_NM, A.CNTR_AMT FROM OP_USER B JOIN G_CNTR A ON A.USER_ID = B.USER_ID JOIN G_LOCGOV C ON A.CNTR_LOCGOV_CODE = C.LOCGOV_CODE WHERE A.DELETE_AT = 'N' AND A.CNTR_STTUS_CODE = '200' AND B.USER_ID = #{userId}
and a.cntr_locgov_code = #{locgovCode}
and c.upper_locgov_code = #{upperLocgovCode}
and a.cntr_de BETWEEN DATE_FORMAT(#{searchStartDate},'%Y%m%d') AND DATE_FORMAT(#{searchEndDate},'%Y%m%d')
ORDER BY A.CNTR_DE DESC

/* saleson.shop.mypage.MypageMapper.getReceiptPopListInfo */ SELECT A.CNTR_SN , DATE_FORMAT(A.CNTR_DE, '%Y.%c.%e.') as cntr_de, A.CNTR_DE AS origin_cntr_de, C.LOCGOV_CODE, C.UPPER_LOCGOV_NM, C.LOCGOV_NM, C.BIZRNO as BIZ_RNO, A.CNTR_AMT, RANK() OVER (ORDER BY C.LOCGOV_CODE ASC) AS RANK_CODE FROM G_CNTR A JOIN G_LOCGOV C ON A.CNTR_LOCGOV_CODE = C.LOCGOV_CODE WHERE A.CNTR_SN IN
#{cntrSn}
ORDER BY A.CNTR_DE DESC

/* saleson.shop.mypage.MypageMapper.getTopLocGov */ SELECT GC.UPPER_LOCGOV_NM + ' ' + GC.LOCGOV_NM AS locgovNm, COUNT(*) OVER() AS locCount FROM ( SELECT DISTINCT CNTR_LOCGOV_CODE AS LOCGOV_CODE FROM G_CNTR WHERE CNTR_SN IN
#{cntrSn}
) A JOIN G_LOCGOV GC ON A.LOCGOV_CODE = GC.LOCGOV_CODE ORDER BY GC.LOCGOV_CODE LIMIT 1

